TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"partial","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"yes","where":"References"}],"technical_issues":[{"where":"Question 1","issue":"The availability scenario response measure ('the system should stay up most of the time') is qualitative and cannot be objectively measured."},{"where":"Question 3","issue":"In part (c), 99.9975% is only the availability of the redundant payment provider subsystem. The end-to-end availability requires multiplying by the remaining series components (0.9995 * 0.999 * 0.9995 = 0.9980), yielding 99.80% and ~1.5 hours of downtime."},{"where":"Question 4","issue":"No drawback or tuning consideration for the Circuit Breaker pattern was included."},{"where":"Question 5","issue":"Under the CAP theorem, network partitions cannot simply be chosen away in a distributed system; one cannot choose CA over P when a partition occurs."},{"where":"Question 6","issue":"The ADR lacks negative consequences (e.g., added architectural complexity, eventual consistency delays, broker maintenance overhead)."}],"overall":"The submission demonstrates good architectural understanding and strong scenario application in Q2. However, precision suffered across multiple questions: Q1 has an unmeasurable response measure, Q3 omits series components in part (c), Q4 omits drawbacks, Q5 misapplies the CAP theorem, Q6 omits negative consequences, and Q2 exceeds the word limit.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are justified well. The performance scenario is complete with a measurable response measure. However, the availability scenario's response measure ('the system should stay up most of the time') is vague and unmeasurable, placing this in Proficient.","evidence":[{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"The student provides a clear recommendation (modular monolith) backed by two scenario-specific trade-offs: team size vs. operational overhead and addressing existing bottleneck causes without a rewrite. Architectural downsides are explicitly acknowledged.","evidence":[{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Proficient","mark":5.0,"scale":8.0,"points":5.0,"max":8.0,"reasoning":"Parts (a) and (b) are calculated correctly with working. In part (c), the parallel payment provider availability (99.9975%) is mistaken for the overall end-to-end order-placement availability, omitting the series calculation with the other components (should be ~99.80%, ~1.5 h downtime).","evidence":[{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%, which reduces the downtime to 0.000025 × 720 = 0.018 hours"}]},{"id":"C4","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern and its operation (Closed, Open, Half-Open) is accurately explained and applied to the lunch outage. However, no drawbacks or tuning considerations (such as setting thresholds or timeout windows) are provided.","evidence":[{"where":"Question 4","quote":"In the outage last month the breaker would have opened within seconds of the provider slowing down."}]},{"id":"C5","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Both choices are sensible and appropriate concrete techniques are identified (Redis cache and idempotency keys). However, the explanation of the CAP theorem invokes the flawed idea of choosing CA and 'giving up partition tolerance' during network partitions.","evidence":[{"where":"Question 5","quote":"so for payments we choose consistency and availability and give up partition tolerance."}]},{"id":"C6","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"The ADR contains Context, Decision, and Consequences structured specifically around the scenario. However, only positive consequences are detailed; no negative consequences or trade-offs (such as eventual consistency or operational queue management) are listed.","evidence":[{"where":"Question 6","quote":"The queue also smooths the lunch peak because the workers process orders at a steady rate."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"Formatting is clear, headings are followed, and IEEE citations are correctly used. However, Question 2 exceeds the 150-word limit at approximately 181 words.","evidence":[{"where":"Question 2","quote":"I recommend against a full microservices rewrite for the next 12 months."}]}]}
